static List<String> queryWhois(String domain) {
    List<String> wynik = new ArrayList<>();
    try (Socket socket = new Socket("whois.iana.org", 43)) {
        socket.setSoTimeout(5000);
        socket.getOutputStream().write((domain+"\r\n").getBytes(StandardCharsets.UTF_8));
        socket.getOutputStream().flush();
        BufferedReader reader = new BufferedReader(new InputStreamReader(socket.getInputStream()));
        String linia;
        while ((linia = reader.readLine()) != null) wynik.add(linia);
    } catch (IOException e) { /* pusta lista przy bledzie */ }
    return wynik;
}
System.out.println(queryWhois("example.com").size());

static List<String> queryWhoisAt(String host, String domain) {
    List<String> wynik = new ArrayList<>();
    try (Socket socket = new Socket(host, 43)) {
        socket.setSoTimeout(3000);
        socket.getOutputStream().write((domain+"\r\n").getBytes());
        BufferedReader reader = new BufferedReader(new InputStreamReader(socket.getInputStream()));
        String linia;
        while ((linia = reader.readLine()) != null) wynik.add(linia);
    } catch (IOException e) {}
    return wynik;
}
System.out.println(queryWhoisAt("nieistniejacy-whois-server-xyz.invalid", "example.com").isEmpty());

