static boolean containsKeyword(List<String> linie, String keyword) {
    return linie.stream().anyMatch(l -> l.toLowerCase().contains(keyword.toLowerCase()));
}
List<String> odpowiedz = queryWhois("example.com");
System.out.println(containsKeyword(odpowiedz, "refer"));

static String findLineStartingWith(List<String> linie, String prefix) {
    for (String l : linie) if (l.startsWith(prefix)) return l;
    return null;
}
