static int countLines(String domain) {
    try (Socket socket = new Socket("whois.iana.org", 43)) {
        socket.setSoTimeout(5000);
        socket.getOutputStream().write((domain+"\r\n").getBytes());
        BufferedReader reader = new BufferedReader(new InputStreamReader(socket.getInputStream()));
        int licznik = 0;
        while (reader.readLine() != null) licznik++;
        return licznik;
    } catch (IOException e) { return -1; }
}
System.out.println(countLines("example.com"));

