static Map<String,String> parseWhoisFields(List<String> linie) {
    Map<String,String> pola = new LinkedHashMap<>();
    for (String l : linie) {
        int idx = l.indexOf(':');
        if (idx > 0) pola.put(l.substring(0,idx).trim(), l.substring(idx+1).trim());
    }
    return pola;
}
Map<String,String> pola = parseWhoisFields(queryWhois("example.com"));
System.out.println(pola.size()+" pol sparsowanych");

