static Map<String,Integer> batchQuery(List<String> domains) {
    Map<String,Integer> wyniki = new LinkedHashMap<>();
    for (String d : domains) wyniki.put(d, countLines(d));
    return wyniki;
}
System.out.println(batchQuery(List.of("example.com", "wikipedia.org", "example.org")));

static boolean isDomainRegistered(String domain) {
    List<String> odpowiedz = queryWhois(domain);
    String polaczone = String.join(" ", odpowiedz).toLowerCase();
    return !polaczone.contains("no match") && !polaczone.contains("not found");
}
System.out.println(isDomainRegistered("example.com"));

