Map<String,List<String>> cache = new HashMap<>();
static List<String> queryWithCache(Map<String,List<String>> cache, String domain) {
    if (cache.containsKey(domain)) return cache.get(domain);
    List<String> wynik = queryWhois(domain);
    cache.put(domain, wynik);
    return wynik;
}
long t0 = System.nanoTime();
queryWithCache(cache, "example.com");
long pierwsze = (System.nanoTime()-t0)/1_000_000;
t0 = System.nanoTime();
queryWithCache(cache, "example.com");
long drugie = (System.nanoTime()-t0)/1_000_000;
