class WhoisAnalyzer {
    Map<String,Object> analyze(String domain) {
        Map<String,Object> raport = new LinkedHashMap<>();
        List<String> odpowiedz = queryWhois(domain);
        raport.put("liczbaLinii", odpowiedz.size());
        raport.put("pola", parseWhoisFields(odpowiedz));
        raport.put("zarejestrowana", isDomainRegistered(domain));
        return raport;
    }
}
System.out.println(new WhoisAnalyzer().analyze("example.com"));

static List<String> queryWithRetry(String domain, int maxAttempts) throws InterruptedException {
    long opoznienie = 500;
    for (int proba=1;proba<=maxAttempts;proba++) {
        List<String> wynik = queryWhois(domain);
        if (!wynik.isEmpty()) { System.out.println("sukces przy probie "+proba); return wynik; }
        System.out.println("proba "+proba+" nieudana, czekam "+opoznienie+"ms");
        Thread.sleep(opoznienie);
        opoznienie *= 2;
    }
    return List.of();
}
queryWithRetry("example.com", 3);

static String classifyNetworkResult(String host, String domain) {
    try (Socket socket = new Socket(host, 43)) {
        socket.setSoTimeout(5000);
        socket.getOutputStream().write((domain+"\r\n").getBytes());
        BufferedReader reader = new BufferedReader(new InputStreamReader(socket.getInputStream()));
        String linia = reader.readLine();
        return linia != null ? "SUCCESS" : "EMPTY_RESPONSE";
    } catch (SocketTimeoutException e) { return "TIMEOUT"; }
    catch (IOException e) { return "CONNECTION_ERROR"; }
}
System.out.println(classifyNetworkResult("whois.iana.org", "example.com"));
