static Map<String,Object> fullDomainLookup(String domain) {
    Map<String,Object> raport = new LinkedHashMap<>();
    List<String> ianaOdpowiedz = queryWhois(domain);
    raport.put("iana", parseWhoisFields(ianaOdpowiedz));
    String referLinia = findLineStartingWith(ianaOdpowiedz, "refer:");
    if (referLinia != null) {
        String referHost = referLinia.substring("refer:".length()).trim();
        try (Socket s2 = new Socket(referHost, 43)) {
            s2.setSoTimeout(5000);
            s2.getOutputStream().write((domain+"\r\n").getBytes());
            BufferedReader r2 = new BufferedReader(new InputStreamReader(s2.getInputStream()));
            List<String> szczegolowa = new ArrayList<>();
            String l; while ((l = r2.readLine()) != null) szczegolowa.add(l);
            raport.put("rejestr", parseWhoisFields(szczegolowa));
        } catch (IOException e) { raport.put("rejestr", "niedostepny"); }
    }
    return raport;
}
System.out.println(fullDomainLookup("example.com"));
